/// print the same text for the same failure.
fn render_error(
    message: &str,
    status_code: u16,
    headers: Option<&HashMap<String, String>>,
    body: Option<&str>,
) -> String {
    let mut msg = if message.is_empty() {
        "Error message: the server returns an error".to_string()
    } else {
        message.to_string()
    };

    if status_code != 0 {
        msg.push_str(&format!("\nHTTP status code: {}", status_code));
    }
    if let Some(headers) = headers {
        if !headers.is_empty() {
            /* Compact JSON with the keys sorted (D17), so the line is the same
             * on every run and in every SDK. */
            let sorted: std::collections::BTreeMap<&String, String> = headers
                .iter()
                .map(|(name, value)| {
                    let shown = if is_secret_response_header(name) {
                        "***".to_string()
                    } else {
                        value.clone()
                    };
                    (name, shown)
                })
                .collect();
            let json = serde_json::to_string(&sorted).unwrap_or_default();
            msg.push_str(&format!("\nResponse headers: {}", json));
        }
    }
    if let Some(body) = body {
        if !body.is_empty() {
            msg.push_str(&format!("\nResponse body: {}", render_body(body)));
        }
    }
    msg
}

